import { content } from '@promptfall/sim'
import { describe, expect, it } from 'vitest'
import { contentReference } from './content'

describe('content reference', () => {
  const lines = contentReference(content).split('\n')

  it('opens by saying it is generated, and by what', () => {
    expect(lines[0]).toMatch(/^# /)
    expect(lines).toContain(
      "Generated by `pnpm content` (`scripts/content.ts`) from the sim's `content` export. Change the sim, then regenerate.",
    )
  })

  it('lists a zone with its four enemies, boss and turn boss by name', () => {
    expect(lines).toContain(
      '| 2 | Whisperwood | Bramble Wolf, Moss Golem, Wood Goblin, Whisper Wisp | Elder Treant | Owlbear Cub |',
    )
  })

  it('lists enemies and bosses by id, name and archetype', () => {
    expect(lines).toContain('| `elder_treant` | Elder Treant | boss |')
    expect(lines).toContain("| `will_o_wisp` | Will-o'-Wisp | caster |")
  })

  it('lists item bases by id, name, glyph and slot, escaping a pipe glyph', () => {
    expect(lines).toContain('| `oak_staff` | Oak Staff | `\\|` | weapon |')
    expect(lines).toContain('| `iron_sword` | Iron Sword | `/` | weapon |')
  })

  it('lists hero templates by id, name and class', () => {
    expect(lines).toContain('| `knight_1` | Aldric | knight |')
  })

  it('lists the rarities with their level caps', () => {
    expect(lines).toContain('| common | 20 |')
    expect(lines).toContain('| legendary | 50 |')
  })

  it('holds one row per registry entry', () => {
    const rows = lines.filter((l) => /^\| [\d`a-z]/.test(l))
    const expected =
      content.zones.length +
      Object.keys(content.enemies).length +
      Object.keys(content.itemBases).length +
      Object.keys(content.heroTemplates).length +
      Object.keys(content.rarity).length
    expect(rows).toHaveLength(expected)
  })
})
